            } else if (UTF8Offset + 2 < index + len && str.charAt(UTF8Offset + 2) == 0xBF) { // Byte for continuation of multibyte encoding 2
                UTF8Offset += 3;
            } else { // Reached end of multibyte encoding
                return size;
            }
        } else {
