public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }
    for (int i = 0; i < str.length(); ++i) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            // 7 bit ASCII
            lb.put((byte)(c));
        } else if (c <= 0x7FF) {
            // 11 bit UTF-8
            lb.put((byte)(0xC0 | (c >> 6)));
            lb.put((byte)(0x80 | (c & 0x3F)));
        } else if (c <= 0xFFFF) {
            // 16 bit UTF-8
            lb.put((byte)(0xE0 | (c >> 12)));
            lb.put((byte)(0x80 | ((c >> 6) & 0x3F)));
            lb.put((byte)(0x80 | (c & 0x3F)));
        } else {
            // 32 bit UTF-8 (Unicode)
            lb.put((byte)(0xF0 | (c >> 18)));
            lb.put((byte)(0x80 | ((c >> 12) & 0x3F)));
            lb.put((byte)(0x80 | ((c >> 6) & 0x3F)));
            lb.put((byte)(0x80 | (c & 0x3F)));
        }
    }
    return lb;
}
