private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    if (vertices.size() <= 1) {
        return true;
    }

    Iterator<E> iterator = vertices.iterator();
    V firstVertex = iterator.next();

    for (V vertex : vertices) {
        if (!graph.containsEdge(firstVertex, vertex)) {
            return false;
        }
    }

    return true;
}
